def patch_homepage() -> None:
    path = ROOT / "index.html"
    doc = path.read_text(encoding="utf-8")
    css = f'''{HUB_CSS_START}
.topic-home-grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-top:24px}}
.topic-home-card{{padding:18px;border:1px solid #e1e9e3;border-radius:14px;background:#fff}}
.topic-home-card b{{display:block;font-size:14px;color:#34483c;margin-bottom:5px}}
.topic-home-card span{{font-size:10px;color:#267a4a;font-weight:900}}
.topic-home-actions{{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}}
@media(max-width:780px){{.topic-home-grid{{grid-template-columns:1fr 1fr}}}}
@media(max-width:460px){{.topic-home-grid{{grid-template-columns:1fr}}}}
{HUB_CSS_END}'''
    if HUB_CSS_START in doc and HUB_CSS_END in doc:
        doc = re.sub(re.escape(HUB_CSS_START) + r".*?" + re.escape(HUB_CSS_END), css, doc, count=1, flags=re.S)
    else:
        doc = doc.replace("footer{", css + "\nfooter{", 1)
    featured_slugs = ["postpartum-care", "fertility-preconception", "hyperhidrosis", "chronic-complex-symptoms", "chronic-fatigue", "insomnia", "rhinitis-postnasal", "reflux-dyspepsia", "tic-support", "low-back-disc-stenosis", "knee-arthritis", "diet-metabolic"]
    lookup = {t["slug"]: t for t in TOPICS}
    cards = "".join(f'<a class="topic-home-card" href="topic-{s}.html"><span>{esc(lookup[s]["category"])}</span><b>{esc(lookup[s]["name"])}</b></a>' for s in featured_slugs)
    section = f'''{HUB_START}<section class="section mint" id="symptom-topics"><div class="container"><div class="section-label">SYMPTOM & LIFE-STAGE GUIDE</div><h2 class="section-title">증상과 목적에 맞춰 찾아보세요</h2><p class="section-desc">산후회복·임신준비부터 다한증, 만성피로, 수면, 소아, 소화기, 통증까지 다양한 건강 고민을 주제별로 정리했습니다.</p><div class="topic-home-grid">{cards}</div><div class="topic-home-actions"><a class="btn primary" href="topics.html">전체 증상·목적별 정보 보기 →</a><a class="btn" href="naver-blog.html">네이버 블로그 최신 글 →</a></div></div></section>{HUB_END}'''
    if HUB_START in doc and HUB_END in doc:
        doc = re.sub(re.escape(HUB_START) + r".*?" + re.escape(HUB_END), section, doc, count=1, flags=re.S)
    else:
        marker = '<section class="section" id="information">'
        if marker in doc:
            doc = doc.replace(marker, section + "\n" + marker, 1)
        else:
            doc = doc.replace("</main>", section + "\n</main>", 1)
    # Add navigation once.
    if 'href="topics.html"' not in doc.split("</nav>", 1)[0]:
        doc = doc.replace('      <a href="index.html#clinic">진료분야</a>', '      <a href="index.html#clinic">진료분야</a>\n      <a href="topics.html">증상·목적별</a>', 1)
    # Add search/AI-friendly knowsAbout to clinic structured data without changing factual care claims.
    m = re.search(r'<script type="application/ld\+json">(.*?)</script>', doc, flags=re.S)
    if m:
        try:
            data = json.loads(m.group(1))
            graph = data.get("@graph", []) if isinstance(data, dict) else []
            for node in graph:
                if isinstance(node, dict) and node.get("@id") == f"{BASE}/#clinic":
                    node["knowsAbout"] = [t["name"] for t in TOPICS]
                    node["hasOfferCatalog"] = {
                        "@type": "OfferCatalog",
                        "name": "증상·목적별 진료정보",
                        "url": f"{BASE}/topics.html",
                    }
                    break
            new_block = '<script type="application/ld+json">' + json.dumps(data, ensure_ascii=False, separators=(",", ":")) + "</script>"
            doc = doc[:m.start()] + new_block + doc[m.end():]
        except Exception:
            pass
    path.write_text(doc, encoding="utf-8")


def patch_llms() -> None:
    path = ROOT / "llms.txt"
    text = path.read_text(encoding="utf-8") if path.exists() else f"# {CLINIC}\n\n"
    start = "<!-- TOPIC_GUIDES_START -->"
    end = "<!-- TOPIC_GUIDES_END -->"
    lines = [start, "## 증상·목적별 상세 가이드", f"- [전체 주제 보기]({BASE}/topics.html)"]
    for t in TOPICS:
        lines.append(f'- [{t["name"]}]({BASE}/topic-{t["slug"]}.html) — {t["description"]}')
    lines.append(end)
    block = "\n".join(lines)
    if start in text and end in text:
        text = re.sub(re.escape(start) + r".*?" + re.escape(end), block, text, flags=re.S)
    else:
        text = text.rstrip() + "\n\n" + block + "\n"
    path.write_text(text, encoding="utf-8")


def patch_sitemap() -> None:
    html_files = sorted(ROOT.glob("*.html"), key=lambda p: (p.name != "index.html", p.name))
    urls = []
    for p in html_files:
        loc = f"{BASE}/" if p.name == "index.html" else f"{BASE}/{p.name}"
        urls.append(f"  <url><loc>{html.escape(loc)}</loc><lastmod>{TODAY}</lastmod></url>")
    xml = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + "\n".join(urls) + "\n</urlset>\n"
    (ROOT / "sitemap.xml").write_text(xml, encoding="utf-8")


def main() -> None:
    generate_topics()
    (ROOT / "topics.html").write_text(hub_page(), encoding="utf-8")
    patch_homepage()
    patch_llms()
    patch_sitemap()
    print(f"Generated {len(TOPICS)} topic pages plus hub, homepage links, llms.txt and sitemap.xml")


if __name__ == "__main__":
    main()
